-- AI assistant (BYOK): per-user conversation threads + encrypted provider credentials.
--
-- Note: generated by `supabase db diff` from supabase/schemas, then trimmed by hand.
-- The diff tool also emitted unrelated statements (drop extension pgjwt, view
-- re-creations) and default grants to anon/authenticated; those were removed on
-- purpose. Credentials must be reachable by service_role only.

create table public.assistant_threads (
    id uuid primary key default gen_random_uuid(),
    user_id uuid not null references auth.users(id) on delete cascade,
    durable_conversation_id text not null,
    title text not null default 'New conversation',
    created_at timestamp with time zone not null default now(),
    updated_at timestamp with time zone not null default now(),
    last_message_at timestamp with time zone
);

create index assistant_threads_user_id_idx on public.assistant_threads using btree (user_id);

create table public.assistant_credentials (
    user_id uuid primary key references auth.users(id) on delete cascade,
    base_url text not null,
    model text not null,
    api_key_ciphertext text not null,
    api_key_hint text not null default '',
    created_at timestamp with time zone not null default now(),
    updated_at timestamp with time zone not null default now()
);

alter table public.assistant_threads enable row level security;
alter table public.assistant_credentials enable row level security;

-- Threads: a user only sees and manages their own.
create policy "assistant_threads_select_own" on public.assistant_threads
    for select to authenticated using (user_id = auth.uid());
create policy "assistant_threads_insert_own" on public.assistant_threads
    for insert to authenticated with check (user_id = auth.uid());
create policy "assistant_threads_update_own" on public.assistant_threads
    for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "assistant_threads_delete_own" on public.assistant_threads
    for delete to authenticated using (user_id = auth.uid());

-- Credentials: RLS enabled with no policy => only service_role can read/write them.
revoke all on table public.assistant_credentials from anon;
revoke all on table public.assistant_credentials from authenticated;

revoke all on table public.assistant_threads from anon;

grant all on table public.assistant_threads to authenticated;
grant all on table public.assistant_threads to service_role;
grant all on table public.assistant_credentials to service_role;
